/** Bounds of the rounded fixture, [minimumX, minimumY, maximumX, maximumY], metres. */
export const CHICAGO_WINDOW_BOUNDS: readonly [number, number, number, number] = [
  -18204.9765625, -21009.462890625, 16332, 21021.8515625
];

/** Binary64 shoelace area of the rounded fixture, subtracting holes, square metres. */
export const CHICAGO_WINDOW_AREA = 598122247.2741276;

/** Binary64 area before coordinate rounding, square metres. */
export const CHICAGO_WINDOW_UNROUNDED_AREA = 598122247.8973397;

/** Binary64 even-odd point-in-polygon on the fixture rings; CPU test-fixture helper only. */
export function isInsideChicagoWindow(east: number, north: number): boolean {
  const {positions, ringOffsets} = CHICAGO_WINDOW;
  let inside = false;
  for (let ring = 0; ring + 1 < ringOffsets.length; ring++) {
    const begin = ringOffsets[ring];
    const end = ringOffsets[ring + 1];
    for (let vertex = begin; vertex < end; vertex++) {
      const next = vertex + 1 === end ? begin : vertex + 1;
      const startX = positions[2 * vertex];
      const startY = positions[2 * vertex + 1];
      const endX = positions[2 * next];
      const endY = positions[2 * next + 1];
      if (
        startY > north !== endY > north &&
        east < startX + ((endX - startX) * (north - startY)) / (endY - startY)
      ) {
        inside = !inside;
      }
    }
  }
  return inside;
}

/**
 * Deterministic Thomas-like test pattern: 64 uniform in-window parents, Gaussian offspring with
 * 650 m standard deviation, conditioned on falling inside the city. This is a benchmark workload,
 * not a fitted point-process model. Membership is checked after float32 rounding in binary64.
 */
export function createChicagoPattern(count: number, seed: number): Float32Array {
  let state = seed >>> 0;
  const random = () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return (state + 0.5) / 0x100000000;
  };
  const [minimumX, minimumY, maximumX, maximumY] = CHICAGO_WINDOW_BOUNDS;
  const parents: [number, number][] = [];
  while (parents.length < 64) {
    const east = minimumX + random() * (maximumX - minimumX);
    const north = minimumY + random() * (maximumY - minimumY);
    if (isInsideChicagoWindow(east, north)) parents.push([east, north]);
  }
  const positions = new Float32Array(count * 2);
  for (let row = 0; row < count; ) {
    const parent = parents[Math.floor(random() * parents.length)];
    const magnitude = 650 * Math.sqrt(-2 * Math.log(random()));
    const angle = 2 * Math.PI * random();
    const east = Math.fround(parent[0] + magnitude * Math.cos(angle));
    const north = Math.fround(parent[1] + magnitude * Math.sin(angle));
    if (isInsideChicagoWindow(east, north)) {
      positions[2 * row] = east;
      positions[2 * row + 1] = north;
      row++;
    }
  }
  return positions;
}
